messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Three.js Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// --- Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x202025);
scene.fog = new THREE.Fog(0x202025, 10, 25);

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 1.5, 5);
camera.lookAt(0, 1.0, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(-3, 5, 4);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0xff8844, 0.3, 8);
pointLight.position.set(2, 3, 2);
scene.add(pointLight);

// --- Materials ---
const skinMat = new THREE.MeshStandardMaterial({ color: 0xf4c07a, roughness: 0.8 });
const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3366aa, roughness: 0.7 });
const pantsMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3a, roughness: 0.7 });
const shoeMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.5 });
const treadmillMat = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.4, metalness: 0.3 });
const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.3, metalness: 0.5 });
const accentMat = new THREE.MeshStandardMaterial({ color: 0xff4444, roughness: 0.5 });

// --- Treadmill ---
const treadmillGroup = new THREE.Group();

// Base/platform
const baseGeo = new THREE.BoxGeometry(1.8, 0.15, 4);
const base = new THREE.Mesh(baseGeo, treadmillMat);
base.position.y = 0.075;
base.castShadow = true;
base.receiveShadow = true;
treadmillGroup.add(base);

// Belt (top surface)
const beltGeo = new THREE.BoxGeometry(1.6, 0.05, 3.6);
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.position.y = 0.175;
belt.receiveShadow = true;
treadmillGroup.add(belt);

// Belt rollers (left)
for (let i = 0; i < 6; i++) {
    const rollerGeo = new THREE.CylinderGeometry(0.06, 0.06, 1.5, 8);
    const roller = new THREE.Mesh(rollerGeo, new THREE.MeshStandardMaterial({ color: 0x555555, metalness: 0.6 }));
    roller.rotation.x = Math.PI / 2;
    roller.position.set(0, 0.15, -1.5 + i * 0.6);
    roller.castShadow = true;
    treadmillGroup.add(roller);
}

// Belt rollers (right)
for (let i = 0; i < 6; i++) {
    const rollerGeo = new THREE.CylinderGeometry(0.06, 0.06, 1.5, 8);
    const roller = new THREE.Mesh(rollerGeo, new THREE.MeshStandardMaterial({ color: 0x555555, metalness: 0.6 }));
    roller.rotation.x = Math.PI / 2;
    roller.position.set(0, 0.15, -1.5 + i * 0.6);
    roller.castShadow = true;
    treadmillGroup.add(roller);
}

// Side rails
const railGeo = new THREE.BoxGeometry(0.06, 0.06, 3.8);
const railL = new THREE.Mesh(railGeo, accentMat);
railL.position.set(-0.85, 0.25, 0);
treadmillGroup.add(railL);
const railR = new THREE.Mesh(railGeo, accentMat);
railR.position.set(0.85, 0.25, 0);
treadmillGroup.add(railR);

// Support legs
const legGeo = new THREE.BoxGeometry(0.08, 0.15, 0.08);
[[-0.85, -1.7], [-0.85, 1.7], [0.85, -1.7], [0.85, 1.7]].forEach(([x, z]) => {
    const leg = new THREE.Mesh(legGeo, treadmillMat);
    leg.position.set(x, 0.0, z);
    leg.castShadow = true;
    treadmillGroup.add(leg);
});

treadmillGroup.position.y = 0;
scene.add(treadmillGroup);

// --- Humanoid ---
const human = new THREE.Group();

// Helper to create a limb with pivot
function createLimb(group, geo, mat, pos, pivot) {
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.position.copy(pos);
    group.add(mesh);
    return mesh;
}

// Torso
const torsoGeo = new THREE.BoxGeometry(0.5, 0.65, 0.3);
const torso = new THREE.Mesh(torsoGeo, shirtMat);
torso.position.y = 1.35;
torso.castShadow = true;
human.add(torso);

// Chest/shoulders (slightly wider)
const chestGeo = new THREE.BoxGeometry(0.55, 0.3, 0.32);
const chest = new THREE.Mesh(chestGeo, shirtMat);
chest.position.y = 1.58;
chest.castShadow = true;
human.add(chest);

// Head
const headGeo = new THREE.BoxGeometry(0.3, 0.32, 0.3);
const head = new THREE.Mesh(headGeo, skinMat);
head.position.y = 1.95;
head.castShadow = true;
human.add(head);

// Neck
const neckGeo = new THREE.BoxGeometry(0.15, 0.12, 0.15);
const neck = new THREE.Mesh(neckGeo, skinMat);
neck.position.y = 1.78;
human.add(neck);

// Hips
const hipsGeo = new THREE.BoxGeometry(0.42, 0.2, 0.28);
const hips = new THREE.Mesh(hipsGeo, pantsMat);
hips.position.y = 1.0;
hips.castShadow = true;
human.add(hips);

// --- Left Arm ---
const leftUpperArm = new THREE.Group();
leftUpperArm.position.set(-0.35, 1.6, 0);
human.add(leftUpperArm);
const luaGeo = new THREE.BoxGeometry(0.14, 0.3, 0.14);
const luaMesh = new THREE.Mesh(luaGeo, shirtMat);
luaMesh.position.y = -0.15;
luaMesh.castShadow = true;
leftUpperArm.add(luaMesh);

const leftLowerArm = new THREE.Group();
leftLowerArm.position.set(0, -0.3, 0);
leftUpperArm.add(leftLowerArm);
const llaGeo = new THREE.BoxGeometry(0.12, 0.28, 0.12);
const llaMesh = new THREE.Mesh(llaGeo, skinMat);
llaMesh.position.y = -0.14;
llaMesh.castShadow = true;
leftLowerArm.add(llaMesh);

// Left hand
const lhGeo = new THREE.BoxGeometry(0.1, 0.08, 0.1);
const lhMesh = new THREE.Mesh(lhGeo, skinMat);
lhMesh.position.y = -0.3;
leftLowerArm.add(lhMesh);

// --- Right Arm ---
const rightUpperArm = new THREE.Group();
rightUpperArm.position.set(0.35, 1.6, 0);
human.add(rightUpperArm);
const ruaGeo = new THREE.BoxGeometry(0.14, 0.3, 0.14);
const ruaMesh = new THREE.Mesh(ruaGeo, shirtMat);
ruaMesh.position.y = -0.15;
ruaMesh.castShadow = true;
rightUpperArm.add(ruaMesh);

const rightLowerArm = new THREE.Group();
rightLowerArm.position.set(0, -0.3, 0);
rightUpperArm.add(rightLowerArm);
const rlaGeo = new THREE.BoxGeometry(0.12, 0.28, 0.12);
const rlaMesh = new THREE.Mesh(rlaGeo, skinMat);
rlaMesh.position.y = -0.14;
rlaMesh.castShadow = true;
rightLowerArm.add(rlaMesh);

// Right hand
const rhGeo = new THREE.BoxGeometry(0.1, 0.08, 0.1);
const rhMesh = new THREE.Mesh(rhGeo, skinMat);
rhMesh.position.y = -0.3;
rightLowerArm.add(rhMesh);

// --- Left Leg ---
const leftUpperLeg = new THREE.Group();
leftUpperLeg.position.set(-0.15, 0.9, 0);
human.add(leftUpperLeg);
const lulGeo = new THREE.BoxGeometry(0.16, 0.38, 0.16);
const lulMesh = new THREE.Mesh(lulGeo, pantsMat);
lulMesh.position.y = -0.19;
lulMesh.castShadow = true;
leftUpperLeg.add(lulMesh);

const leftLowerLeg = new THREE.Group();
leftLowerLeg.position.set(0, -0.38, 0);
leftUpperLeg.add(leftLowerLeg);
const lllGeo = new THREE.BoxGeometry(0.14, 0.36, 0.14);
const lllMesh = new THREE.Mesh(lllGeo, pantsMat);
lllMesh.position.y = -0.18;
lllMesh.castShadow = true;
leftLowerLeg.add(lllMesh);

// Left foot
const lfGeo = new THREE.BoxGeometry(0.14, 0.06, 0.22);
const lfMesh = new THREE.Mesh(lfGeo, shoeMat);
lfMesh.position.set(0, -0.38, 0.04);
leftLowerLeg.add(lfMesh);

// --- Right Leg ---
const rightUpperLeg = new THREE.Group();
rightUpperLeg.position.set(0.15, 0.9, 0);
human.add(rightUpperLeg);
const rulGeo = new THREE.BoxGeometry(0.16, 0.38, 0.16);
const rulMesh = new THREE.Mesh(rulGeo, pantsMat);
rulMesh.position.y = -0.19;
rulMesh.castShadow = true;
rightUpperLeg.add(rulMesh);

const rightLowerLeg = new THREE.Group();
rightLowerLeg.position.set(0, -0.38, 0);
rightUpperLeg.add(rightLowerLeg);
const rllGeo = new THREE.BoxGeometry(0.14, 0.36, 0.14);
const rllMesh = new THREE.Mesh(rllGeo, pantsMat);
rllMesh.position.y = -0.18;
rllMesh.castShadow = true;
rightLowerLeg.add(rllMesh);

// Right foot
const rfGeo = new THREE.BoxGeometry(0.14, 0.06, 0.22);
const rfMesh = new THREE.Mesh(rfGeo, shoeMat);
rfMesh.position.set(0, -0.38, 0.04);
rightLowerLeg.add(rfMesh);

// Position human on treadmill
human.position.set(0, 0.175, 0);
scene.add(human);

// --- Animation State ---
const CYCLE_DURATION = 10.0; // seconds
const STAND_TIME = 2.0;
const WALK_TIME = 3.0;
const RUN_TIME = 3.0;
const STAND2_TIME = 2.0;

// Animation parameters
const WALK_SWING = 0.6;    // radians
const WALK_KNEE = 0.5;     // radians
const WALK_ARM_SWING = 0.5;
const WALK_SPEED = 1.5;    // speed multiplier on sine

const RUN_SWING = 1.0;     // radians
const RUN_KNEE = 1.0;      // radians
const RUN_ARM_SWING = 1.2;
const RUN_SPEED = 3.5;     // speed multiplier
const RUN_LEAN = 0.12;     // radians forward lean

// --- State calculation ---
function getPhase(elapsed) {
    const t = elapsed % CYCLE_DURATION;
    if (t < STAND_TIME) return { phase: 'stand1', t, progress: t / STAND_TIME };
    if (t < STAND_TIME + WALK_TIME) return { phase: 'walk', t: t - STAND_TIME, progress: (t - STAND_TIME) / WALK_TIME };
    if (t < STAND_TIME + WALK_TIME + RUN_TIME) return { phase: 'run', t: t - STAND_TIME - WALK_TIME, progress: (t - STAND_TIME - WALK_TIME) / RUN_TIME };
    return { phase: 'stand2', t: t - STAND_TIME - WALK_TIME - RUN_TIME, progress: (t - STAND_TIME - WALK_TIME - RUN_TIME) / STAND2_TIME };
}

// --- Smooth transitions ---
function smoothstep(t) {
    return t * t * (3 - 2 * t);
}

// --- Animation loop ---
const clock = new THREE.Clock();
let prevTime = 0;

function animate() {
    requestAnimationFrame(animate);

    const elapsed = clock.getElapsedTime();
    const dt = elapsed - prevTime;
    prevTime = elapsed;

    const { phase, t, progress } = getPhase(elapsed);

    // --- Transitions ---
    const TRANSITION = 0.3; // seconds for smooth transitions

    let standBlend = 0; // 1 = fully standing still, 0 = fully animated
    let walkBlend = 0;
    let runBlend = 0;

    if (phase === 'stand1') {
        standBlend = 1;
    } else if (phase === 'walk') {
        if (t < TRANSITION) {
            standBlend = 1 - smoothstep(t / TRANSITION);
        }
        walkBlend = t < TRANSITION ? smoothstep(t / TRANSITION) : 1;
    } else if (phase === 'run') {
        if (t < TRANSITION) {
            walkBlend = 1 - smoothstep(t / TRANSITION);
        }
        runBlend = t < TRANSITION ? smoothstep(t / TRANSITION) : 1;
        if (t > RUN_TIME - TRANSITION) {
            runBlend = 1 - smoothstep((t - (RUN_TIME - TRANSITION)) / TRANSITION);
        }
    } else if (phase === 'stand2') {
        if (t < TRANSITION) {
            runBlend = 1 - smoothstep(t / TRANSITION);
        }
        standBlend = t < TRANSITION ? smoothstep(t / TRANSITION) : 1;
    }

    // --- Apply animation ---
    const sine = Math.sin(t * WALK_SPEED);
    const sineRun = Math.sin(t * RUN_SPEED);

    // Standing pose (neutral)
    const standPose = {
        leftArmRot: 0,
        rightArmRot: 0,
        leftUpperLegRot: 0,
        rightUpperLegRot: 0,
        leftLowerLegRot: 0,
        rightLowerLegRot: 0,
        torsoRot: 0,
        headRot: 0,
        torsoY: 0,
    };

    // Walking pose
    const walkPose = {
        leftArmRot: Math.sin(t * WALK_SPEED) * WALK_ARM_SWING,
        rightArmRot: -Math.sin(t * WALK_SPEED) * WALK_ARM_SWING,
        leftUpperLegRot: -Math.sin(t * WALK_SPEED) * WALK_SWING,
        rightUpperLegRot: Math.sin(t * WALK_SPEED) * WALK_SWING,
        leftLowerLegRot: Math.max(0, Math.sin(t * WALK_SPEED)) * WALK_KNEE,
        rightLowerLegRot: Math.max(0, -Math.sin(t * WALK_SPEED)) * WALK_KNEE,
        torsoRot: 0,
        headRot: 0,
        torsoY: 0.03 * Math.abs(Math.sin(t * WALK_SPEED * 2)),
    };

    // Running pose
    const runPose = {
        leftArmRot: Math.sin(t * RUN_SPEED) * RUN_ARM_SWING * 1.2,
        rightArmRot: -Math.sin(t * RUN_SPEED) * RUN_ARM_SWING * 1.2,
        leftUpperLegRot: -Math.sin(t * RUN_SPEED) * RUN_SWING * 1.1,
        rightUpperLegRot: Math.sin(t * RUN_SPEED) * RUN_SWING * 1.1,
        leftLowerLegRot: Math.max(0, Math.sin(t * RUN_SPEED)) * RUN_KNEE * 1.3,
        rightLowerLegRot: Math.max(0, -Math.sin(t * RUN_SPEED)) * RUN_KNEE * 1.3,
        torsoRot: RUN_LEAN,
        headRot: -RUN_LEAN * 0.5,
        torsoY: 0.06 * Math.abs(Math.sin(t * RUN_SPEED * 2)),
    };

    // Blend all parts
    const lArmRot = standPose.leftArmRot * standBlend + walkPose.leftArmRot * walkBlend + runPose.leftArmRot * runBlend;
    const rArmRot = standPose.rightArmRot * standBlend + walkPose.rightArmRot * walkBlend + runPose.rightArmRot * runBlend;
    const lULegRot = standPose.leftUpperLegRot * standBlend + walkPose.leftUpperLegRot * walkBlend + runPose.leftUpperLegRot * runBlend;
    const rULegRot = standPose.rightUpperLegRot * standBlend + walkPose.rightUpperLegRot * walkBlend + runPose.rightUpperLegRot * runBlend;
    const lLLegRot = standPose.leftLowerLegRot * standBlend + walkPose.leftLowerLegRot * walkBlend + runPose.leftLowerLegRot * runBlend;
    const rLLegRot = standPose.rightLowerLegRot * standBlend + walkPose.rightLowerLegRot * walkBlend + runPose.rightLowerLegRot * runBlend;
    const torsoR = standPose.torsoRot * standBlend + walkPose.torsoRot * walkBlend + runPose.torsoRot * runBlend;
    const headR = standPose.headRot * standBlend + walkPose.headRot * walkBlend + runPose.headRot * runBlend;
    const torsoY = standPose.torsoY * standBlend + walkPose.torsoY * walkBlend + runPose.torsoY * runBlend;

    // --- Apply rotations ---
    // Arms swing forward/back (rotate around Z axis for side view)
    leftUpperArm.rotation.z = lArmRot;
    rightUpperArm.rotation.z = rArmRot;

    // Forearms bend slightly
    leftLowerArm.rotation.z = Math.max(0, lArmRot) * 0.4 + 0.1;
    rightLowerArm.rotation.z = Math.max(0, rArmRot) * 0.4 + 0.1;

    // Legs
    leftUpperLeg.rotation.z = lULegRot;
    rightUpperLeg.rotation.z = rULegRot;

    leftLowerLeg.rotation.z = lLLegRot;
    rightLowerLeg.rotation.z = rLLegRot;

    // Torso lean (forward lean during running)
    torso.rotation.z = torsoR;
    head.rotation.z = headR;

    // Torso bob
    human.position.y = 0.175 + torsoY;

    // --- Belt animation ---
    belt.rotation.y = t * 2;

    // --- Camera subtle movement ---
    camera.position.x = Math.sin(elapsed * 0.1) * 0.3;
    camera.position.y = 1.5 + Math.sin(elapsed * 0.15) * 0.05;
    camera.lookAt(0, 1.0, 0);

    renderer.render(scene, camera);
}

// --- Resize handler ---
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// --- Start ---
animate();
</script>
</body>
</html>
